// ---- Consistency (common.schema.json#/$defs/Consistency) ----
/**
 * gate C-3. snapshot_copy: ONE consistent committed database image captured by SQLite's online backup inside one read transaction, read from a published snapshot; live_observation: a point-in-time observation (workspace status, snapshot directory listing); not_applicable: capabilities. sealed_store (capability set 1.1): a sealed attempt-evidence store whose chain, every referenced blob and seal were verified in the same invocation, for the head_digest reported; never returned for an unsealed or failing store.
 */
// ---- SnapshotSummary (snapshot.schema.json#/$defs/SnapshotSummary) ----
export type SnapshotId = string;

export interface SnapshotSummary {
  snapshot_id: SnapshotId;
  acquisition_started_at: string | null;
  acquisition_completed_at: string | null;
  source: string | null;
  source_metadata_at_acquisition: SourceMetadata | null;
  source_metadata_now: SourceMetadata | null;
  source_metadata_changed: boolean | null;
  rows: number | null;
  size: number | null;
  sqlite_version: string | null;
  digest_verified?: boolean;
  [k: string]: unknown;
}
/**
 * Observed by stat() only: size, mtime_ns, inode and side-file sizes. Equality of two observations does NOT establish unchanged contents (gate C-3).
 */
// ---- SnapshotAcquireResult (snapshot.schema.json#/$defs/SnapshotAcquireResult) ----
export type SnapshotAcquireResult = SnapshotSummary & {
  orphans_removed: string[];
  pruned: string[];
  backup_steps: number;
  duration_ms: number;
  [k: string]: unknown;
};
// ---- SnapshotList (snapshot.schema.json#/$defs/SnapshotList) ----
export interface SnapshotList {
  snapshot_directory: string;
  snapshots: SnapshotSummary[];
  retain: number;
  [k: string]: unknown;
}
// ---- SnapshotPrune (snapshot.schema.json#/$defs/SnapshotPrune) ----
export interface SnapshotPrune {
  removed: string[];
  orphans_removed: string[];
  kept: string[];
  [k: string]: unknown;
}

// ---- SnapshotVerify (snapshot.schema.json#/$defs/SnapshotVerify) ----
export interface SnapshotVerify {
  snapshot_id: SnapshotId;
  digest_verified: true;
  sha256: string | null;
  size: number | null;
  verified_at: string;
  duration_ms: number;
  guarantee?: string;
  [k: string]: unknown;
}

// ---- EvidenceManifest (evidence.schema.json#/$defs/EvidenceManifest) ----
export interface EvidenceManifest {
  /**
   * The EVIDENCE run id. null when from_trace could not resolve one (the trace row records no store).
   */
  run_id: string | null;
  store: 'present' | 'absent';
  /**
   * manifest.json verbatim: schema, writer_version, redaction_policy_version, capture, run_id and the run manifest keys.
   */
  manifest: {
    schema?: string;
    writer_version?: string;
    redaction_policy_version?: string;
    /**
     * A capture mode (full, digest_only, full_with_reasoning); a value outside capabilities.features.evidence_capture_modes is shown literally.
     */
    capture?: string;
    [k: string]: unknown;
  } | null;
  /**
   * seal.json verbatim; null when the store is unsealed. An unsealed store does not by itself prove a run is active.
   */
  seal: {
    final_seq?: number;
    head_digest?: string;
    record_count?: number;
    blob_count?: number;
    complete?: boolean;
    gaps?: number;
    degraded?: string[];
    closed_reason?: string;
    [k: string]: unknown;
  } | null;
  /**
   * Complete record lines (a cheap count, not a verification).
   */
  line_count: number | null;
  bytes_on_disk: number | null;
  blob_file_count: number | null;
  absence: EvidenceAbsence | null;
  link: null | {
    trace_run_id: string;
    evidence_run_id: string | null;
    resolved_from: string;
    /**
     * The event details exactly as stored.
     */
    recorded_event: {
      [k: string]: unknown;
    };
    [k: string]: unknown;
  };
  [k: string]: unknown;
}
/**
 * DERIVED (never recorded) reason a run has no store on disk, from the run's recorded evidence.attempt_store event.
 */
export interface EvidenceAbsence {
  reason: 'pruned' | 'capture_off' | 'recorder_unavailable' | 'pre_recorder' | 'unknown';
  derived_from: string;
  detail: string;
  snapshot_id?: string | null;
  /**
   * The evidence.attempt_store event details exactly as stored; null when the event is absent or no snapshot was supplied.
   */
  recorded_event?: {
    [k: string]: unknown;
  };
  [k: string]: unknown;
}

// ---- EvidenceVerify (evidence.schema.json#/$defs/EvidenceVerify) ----
export interface EvidenceVerify {
  run_id: string;
  status: 'VERIFIED' | 'UNSEALED' | 'NOT_FOUND' | 'CHAIN_BROKEN' | 'TRUNCATED_TAIL' | 'BLOB_CORRUPT' | 'SEAL_MISMATCH';
  record_count: number;
  sealed: boolean;
  broken_seq: number | null;
  detail: string;
  seal: {
    [k: string]: unknown;
  } | null;
  blob_problems: string[];
  /**
   * Digest of the last complete record verified in this pass; null when the chain did not verify up to a head.
   */
  head_digest: string | null;
  verified_at: string;
  [k: string]: unknown;
}

// ---- EvidenceRecords (evidence.schema.json#/$defs/EvidenceRecords) ----
export interface EvidenceRecords {
  run_id: string;
  head_digest: string | null;
  records: EvidenceRecord[];
  /**
   * Opaque; bound to the run, the filters and head_digest. null: no further matching record.
   */
  next_cursor: string | null;
  filters_applied: {
    [k: string]: unknown;
  };
  /**
   * true: the page stopped at the response byte budget before the requested limit; next_cursor continues.
   */
  truncated: boolean;
  /**
   * true: an unsealed store ends in a partial record line, which is not served.
   */
  truncated_tail: boolean;
  [k: string]: unknown;
}
/**
 * One record exactly as the recorder stored it (envelope keys in the evidence schema; unknown fields preserved) plus phase_provenance, which the reader computes and never stores.
 */
export interface EvidenceRecord {
  schema: string;
  seq: number;
  prev: string;
  kind: string;
  run_id: string;
  unit_id?: string | null;
  unit_kind?: string | null;
  invocation_seq?: number | null;
  phase?: string | null;
  attempt_number?: number | null;
  call_seq?: number | null;
  wire_seq?: number | null;
  role?: string | null;
  t_wall?: string;
  t_mono_ms?: number;
  /**
   * OBSERVED, DERIVED, MODEL_CLAIMED, MIRRORED, NOT_RECORDED or LEGACY_RECONSTRUCTED (capabilities.features.evidence_provenances); an unknown value is shown literally.
   */
  provenance: string;
  payload: {
    [k: string]: unknown;
  };
  content_digests: {
    [k: string]: unknown;
  };
  /**
   * Blob references (sha256:...) only; content is never inlined.
   */
  blobs: {
    [k: string]: string;
  };
  /**
   * How the record's phase is known; everything but explicit is DERIVED. null: no phase was recorded, or it is an unmapped raw role name (nothing is synthesized).
   */
  phase_provenance: 'explicit' | 'derived_from_attempt_scope' | 'derived_from_role' | null;
  [k: string]: unknown;
}

// ---- EvidenceChangeContent (evidence.schema.json#/$defs/EvidenceChangeContent) ----
/**
 * One authorized part of one recorded candidate change (evidence.change_content). Served only when Kriya's own content_visibility is on; capped; re-hashed on read.
 */
export interface EvidenceChangeContent {
  run_id: string;
  seq: number;
  part: string;
  content_class: string;
  path: string | null;
  attempt: number | null;
  /**
   * The sha256 reference the record names; the bytes below hash to it.
   */
  ref: string;
  bytes_total: number;
  encoding: 'utf-8' | 'base64';
  content: string;
  digest_ok: true;
  head_digest: string | null;
  [k: string]: unknown;
}

// ---- EvidenceCallContent (evidence.schema.json#/$defs/EvidenceCallContent) ----
/**
 * One authorized part of one recorded model request (evidence.call_content): what the model was shown. Served only when Kriya's own content_visibility is on; capped; re-hashed on read; never the model's answer.
 */
export interface EvidenceCallContent {
  run_id: string;
  seq: number;
  part: string;
  content_class: string;
  role: string | null;
  call_seq: number | null;
  attempt: number | null;
  ref: string;
  bytes_total: number;
  encoding: 'utf-8' | 'base64';
  content: string;
  digest_ok: true;
  head_digest: string | null;
  [k: string]: unknown;
}

// ---- KupRequest (host-contract.schema.json#/$defs/KupRequest) ----
/**
 * Exactly the gated grammar (03_GATE.md): history reads are PINNED to a snapshot id (required); acquisition is a separate explicit request; run_id, cursor and snapshot_id are opaque values the host validates before use.
 */
export type KupRequest =
  | {
      operation: 'capabilities';
    }
  | {
      operation: 'snapshot.acquire';
      /**
       * Absolute path without control characters.
       */
      workspace?: string;
    }
  | {
      operation: 'snapshot.list';
      verify?: boolean;
    }
  | {
      operation: 'snapshot.prune';
      keep?: number;
    }
  | {
      operation: 'snapshot.verify';
      snapshot_id: string;
    }
  | {
      operation: 'history.list';
      snapshot_id: string;
      limit?: number;
      cursor?: string;
      /**
       * Only the runs whose evidence manifest records this workspace (Kriya decides; the scope is reported in the result).
       */
      workspace?: string;
    }
  | {
      operation: 'history.detail';
      snapshot_id: string;
      run_id: RunId;
    }
  | {
      operation: 'history.prompt';
      snapshot_id: string;
      run_id: RunId;
    }
  | {
      operation: 'workspace.status';
      /**
       * Absolute path without control characters.
       */
      workspace: string;
    }
  | {
      operation: 'workspace.describe';
      /**
       * Absolute path without control characters.
       */
      workspace: string;
    }
  | {
      operation: 'execution.preflight';
      /**
       * Absolute path without control characters.
       */
      workspace: string;
    }
  | {
      operation: 'workspace.create';
      /**
       * Absolute path without control characters.
       */
      parent: string;
      /**
       * ONE folder name (validated again by Kriya): no separator, no colon, no control character, no leading dot.
       */
      name: string;
    }
  | {
      operation: 'configuration.approval_status';
      /**
       * Absolute path without control characters.
       */
      workspace: string;
    }
  | {
      operation: 'project.initialize';
      /**
       * Absolute path without control characters.
       */
      workspace: string;
    }
  | {
      operation: 'change_approval.review';
      /**
       * Absolute path without control characters.
       */
      workspace: string;
      launch_id: string;
      /**
       * The review identity Kriya gave in launch.status (pending_approval.review_id).
       */
      review_id: string;
    }
  | {
      operation: 'runtime_command.review';
      /**
       * Absolute path without control characters.
       */
      workspace: string;
      launch_id: string;
      /**
       * The review identity Kriya gave in launch.status (pending_approval.review_id).
       */
      review_id: string;
    }
  | {
      operation: 'configuration.approve';
      /**
       * Absolute path without control characters.
       */
      workspace: string;
      /**
       * The review fingerprint Kriya gave with the status this person reviewed; Kriya approves only if the configuration it now resolves has the same fingerprint.
       */
      fingerprint: string;
    }
  | {
      operation: 'execution.context';
      /**
       * Absolute path without control characters.
       */
      workspace: string;
    }
  | {
      operation: 'execution.model_probe';
      /**
       * Absolute path without control characters.
       */
      workspace: string;
    }
  | {
      operation: 'skills.list';
      /**
       * Absolute path without control characters.
       */
      workspace: string;
    }
  | {
      operation: 'skills.describe';
      /**
       * Absolute path without control characters.
       */
      workspace: string;
      /**
       * An item id (a skill name, or mcp:<server> / plugin:<name>). Never a path.
       */
      skill_id: string;
    }
  | {
      operation: 'tools.list';
      /**
       * Absolute path without control characters.
       */
      workspace: string;
    }
  | {
      operation: 'tools.describe';
      /**
       * Absolute path without control characters.
       */
      workspace: string;
      /**
       * An item id (a skill name, or mcp:<server> / plugin:<name>). Never a path.
       */
      tool_id: string;
    }
  | {
      operation: 'tools.approval_state';
      /**
       * Absolute path without control characters.
       */
      workspace: string;
      /**
       * An item id (a skill name, or mcp:<server> / plugin:<name>). Never a path.
       */
      tool_id: string;
    }
  | {
      operation: 'launch.status';
      /**
       * Absolute path without control characters.
       */
      workspace: string;
      /**
       * The shape of a Kriya run id; the launch id IS the run id.
       */
      launch_id: string;
    }
  | {
      operation: 'evidence.manifest';
      run_id: RunId;
      snapshot_id?: string;
      /**
       * run_id is a trace row id; needs snapshot_id.
       */
      from_trace?: boolean;
    }
  | {
      operation: 'evidence.verify';
      run_id: RunId;
    }
  | {
      operation: 'evidence.records';
      run_id: RunId;
      unit?: string;
      phase?: string;
      role?: string;
      attempt?: number;
      from_seq?: number;
      /**
       * @minItems 1
       * @maxItems 40
       */
      kind?: [string, ...string[]];
      limit?: number;
      cursor?: string;
    }
  | {
      operation: 'evidence.change_content';
      run_id: RunId;
      seq: number;
      part: string;
    }
  | {
      operation: 'evidence.call_content';
      run_id: RunId;
      seq: number;
      part: string;
    };
export type RunId = string;

// ---- OpenInIdeRequest (host-contract.schema.json#/$defs/OpenInIdeRequest) ----
export interface OpenInIdeRequest {
  /**
   * A path from recorded data (no control characters); the host opens it only if it is an existing regular file inside the selected workspace.
   */
  path: string;
  line?: number;
}

// ---- OpenInIdeResult (host-contract.schema.json#/$defs/OpenInIdeResult) ----
export type EditorId = 'vscode' | 'intellij' | 'eclipse';

export interface OpenInIdeResult {
  ok: boolean;
  editor: EditorId;
  /**
   * false = the host knows this editor's command form is unverified on this machine.
   */
  verified: boolean;
  message: string;
}

// ---- HostInfo (host-contract.schema.json#/$defs/HostInfo) ----
export interface HostInfo {
  kind: string;
  hostVersion: string;
  /**
   * true while the host answers from fixtures (D-9).
   */
  fixtureMode: boolean;
  /**
   * The validated directory every kriya child runs in (kriya.yaml discovery, SEC-009 classification); null when invalid. Independent of the recovery workspace (08 review F-5).
   */
  configDirectory: string | null;
  configDirectorySource: 'setting' | 'default_home' | 'invalid';
  /**
   * Why the configuration directory is unusable (then every KUP call is a typed HOST_ERROR until it is fixed).
   */
  configDirectoryProblem: string | null;
}

// ---- WorkspaceChoice (host-contract.schema.json#/$defs/WorkspaceChoice) ----
/**
 * Result of the native folder chooser. The host returns a path only; Kriya (workspace.describe) interprets it.
 */
export interface WorkspaceChoice {
  /**
   * false when the person cancelled (a normal outcome: nothing changes).
   */
  chosen: boolean;
  path: string | null;
  /**
   * RUN_ACTIVE: the workspace cannot change while a run this host started is in progress.
   */
  refused?: 'RUN_ACTIVE' | null;
}

// ---- StartRunRequest (host-contract.schema.json#/$defs/StartRunRequest) ----
/**
 * Start Run (GUI M6): the ONLY execution action. The workspace must be the folder currently open in this host (chosen with Open Folder); the goal is the engineering task. There are no other options: a launch is non-interactive and cannot widen Kriya's configuration or authority.
 */
export interface StartRunRequest {
  /**
   * Absolute path without control characters.
   */
  workspace: string;
  goal: string;
}

// ---- StartRunResult (host-contract.schema.json#/$defs/StartRunResult) ----
/**
 * Answer to Start Run. started=true means a Kriya process was launched and a launch id exists (follow it with launch.status); the outcome of the run is only ever in Kriya's durable records. started=false carries Kriya's or the host's typed refusal.
 */
export interface StartRunResult {
  started: boolean;
  launch_id: string | null;
  refusal: {
    code: string;
    message: string;
    blockers?: {
      code: string;
      message: string;
      [k: string]: unknown;
    }[];
  } | null;
}

// ---- ExecutionState (host-contract.schema.json#/$defs/ExecutionState) ----
/**
 * What the HOST knows about the one execution process it started: the process, not the run. It never carries an outcome - Kriya's durable records (launch.status, the trace row, the evidence store) are the outcome. No stdout/stderr text is passed on.
 */
export interface ExecutionState {
  phase: 'idle' | 'starting' | 'running' | 'exited';
  launch_id: string | null;
  workspace: string | null;
  started_at: string | null;
  ended_at: string | null;
  exit: {
    code: number | null;
    signal: string | null;
  } | null;
  /**
   * A typed host-side reason; never process output.
   */
  diagnostic: ('spawn_failed' | 'terminated_by_the_host') | null;
}

// ---- DecideApprovalRequest (host-contract.schema.json#/$defs/DecideApprovalRequest) ----
/**
 * Review decision (GUI final): ONE human decision for the change review that is pending in a launch Kriya recorded. It carries the identities Kriya gave the pending review (launch id, review id, candidate digest) and nothing else - no option can approve 'whatever is current', approve always, or widen Kriya's authority. Kriya (`launch-decision`) validates every identity against its durable state and refuses a stale, replayed, foreign or late request.
 */
export interface DecideApprovalRequest {
  /**
   * Absolute path without control characters.
   */
  workspace: string;
  launch_id: string;
  review_id: string;
  candidate_digest: string;
  decision: 'approve' | 'reject';
}

// ---- DecideApprovalResult (host-contract.schema.json#/$defs/DecideApprovalResult) ----
/**
 * Answer to a review decision. accepted=true means Kriya durably recorded the decision for the waiting run; the run's outcome is only ever in Kriya's durable records. accepted=false carries Kriya's or the host's closed refusal code.
 */
export interface DecideApprovalResult {
  accepted: boolean;
  code: string;
  message: string;
  launch_id?: string | null;
  review_id?: string | null;
  decision?: string | null;
  decided_at?: string | null;
}

// ---- DecideRuntimeCommandRequest (host-contract.schema.json#/$defs/DecideRuntimeCommandRequest) ----
/**
 * Runtime-command decision (GUI-RUNTIME-COMMAND-APPROVAL-001): ONE human decision for the RUNTIME-COMMAND review that is pending in a launch Kriya recorded. It carries only the identities Kriya gave the pending review (launch id, review id, command fingerprint) and the decision - never a command, argument, directory or environment value, so a renderer cannot approve a command Kriya did not propose, change what runs, or approve another run or unit. The host re-proves the review through `runtime_command.review`, shows a native confirmation built from that answer, and only then asks Kriya (`launch-decision --kind runtime_command`), which validates every identity against its durable state.
 */
export interface DecideRuntimeCommandRequest {
  /**
   * Absolute path without control characters.
   */
  workspace: string;
  launch_id: string;
  review_id: string;
  command_fingerprint: string;
  decision: 'approve' | 'reject';
}

// ---- DecideRuntimeCommandResult (host-contract.schema.json#/$defs/DecideRuntimeCommandResult) ----
/**
 * Answer to a runtime-command decision. accepted=true means Kriya durably recorded the decision for the waiting run; the run's outcome is only ever in Kriya's durable records. accepted=false carries Kriya's or the host's closed code; `CONFIRMATION_DECLINED` means the person pressed Cancel on the native confirmation: nothing was sent, nothing was approved, and the review is still waiting.
 */
export interface DecideRuntimeCommandResult {
  accepted: boolean;
  code: string;
  message: string;
  launch_id?: string | null;
  review_id?: string | null;
  decision?: string | null;
  decided_at?: string | null;
}

// ---- ApproveConfigurationRequest (host-contract.schema.json#/$defs/ApproveConfigurationRequest) ----
/**
 * Approve the configuration the person reviewed. Exactly these two fields: the folder (which must be the one the host has open) and the review fingerprint Kriya gave with configuration.approval_status. There is no field for settings, values, a path, a digest to trust or a store location.
 */
export interface ApproveConfigurationRequest {
  /**
   * Absolute path without control characters.
   */
  workspace: string;
  /**
   * The review fingerprint Kriya gave with the status this person reviewed; Kriya approves only if the configuration it now resolves has the same fingerprint.
   */
  fingerprint: string;
}

// ---- ApproveConfigurationResult (host-contract.schema.json#/$defs/ApproveConfigurationResult) ----
/**
 * Kriya's answer to an approval request, passed through. approved=true means Kriya wrote (or found already current) the approval for exactly the reviewed configuration. approved=false with outcome 'declined' (and no code) means the person pressed Cancel in the host's native confirmation: a normal decision, Kriya was not asked and nothing was written. Otherwise approved=false carries a closed code: APPROVAL_STALE (the configuration changed after it was reviewed; nothing was approved), APPROVAL_UNAVAILABLE, or a host refusal such as WORKSPACE_NOT_OPEN, INVALID_REQUEST, RUN_ACTIVE, APPROVAL_IN_FLIGHT.
 */
export interface ApproveConfigurationResult {
  approved: boolean;
  outcome: string | null;
  code: string | null;
  message: string | null;
  reason: string | null;
}

// ---- RecentWorkspaces (host-contract.schema.json#/$defs/RecentWorkspaces) ----
/**
 * A bounded, most-recent-first list of folders previously opened. Remembered paths are NOT trusted: opening one runs the same Kriya validation.
 *
 * @maxItems 10
 *
 * Items: Absolute path without control characters.
 */
export type RecentWorkspaces =
  | []
  | [string]
  | [string, string]
  | [string, string, string]
  | [string, string, string, string]
  | [string, string, string, string, string]
  | [string, string, string, string, string, string]
  | [string, string, string, string, string, string, string]
  | [string, string, string, string, string, string, string, string]
  | [string, string, string, string, string, string, string, string, string]
  | [string, string, string, string, string, string, string, string, string, string];

// ---- HostMessages (host-contract.schema.json#/$defs/Messages) ----
/**
 * Exactly the gated grammar (03_GATE.md): history reads are PINNED to a snapshot id (required); acquisition is a separate explicit request; run_id, cursor and snapshot_id are opaque values the host validates before use.
 */
export type SettingKey = 'editor' | 'kriyaExecutable' | 'workspacePath' | 'configDirectory';
export type SettingValue = string | null;
/**
 * A bounded, most-recent-first list of folders previously opened. Remembered paths are NOT trusted: opening one runs the same Kriya validation.
 *
 * @maxItems 10
 *
 * Items: Absolute path without control characters.
 */
export interface HostMessages {
  query?: {
    request?: KupRequest;
    response?: Envelope;
    [k: string]: unknown;
  };
  openInIde?: {
    request?: OpenInIdeRequest;
    response?: OpenInIdeResult;
    [k: string]: unknown;
  };
  copyToClipboard?: {
    request?: string;
    response?: null;
    [k: string]: unknown;
  };
  getSetting?: {
    request?: SettingKey;
    response?: SettingValue;
    [k: string]: unknown;
  };
  setSetting?: {
    request?: {
      key: SettingKey;
      value: SettingValue;
    };
    response?: null;
    [k: string]: unknown;
  };
  hostInfo?: {
    request?: null;
    response?: HostInfo;
    [k: string]: unknown;
  };
  chooseWorkspace?: {
    request?: null;
    response?: WorkspaceChoice;
    [k: string]: unknown;
  };
  recentWorkspaces?: {
    request?: null;
    response?: RecentWorkspaces;
    [k: string]: unknown;
  };
  rememberWorkspace?: {
    /**
     * Absolute path without control characters.
     */
    request?: string;
    response?: RecentWorkspaces;
    [k: string]: unknown;
  };
  forgetWorkspace?: {
    /**
     * Absolute path without control characters.
     */
    request?: string;
    response?: RecentWorkspaces;
    [k: string]: unknown;
  };
  startRun?: {
    request?: StartRunRequest;
    response?: StartRunResult;
    [k: string]: unknown;
  };
  executionState?: {
    request?: null;
    response?: ExecutionState;
    [k: string]: unknown;
  };
  decideApproval?: {
    request?: DecideApprovalRequest;
    response?: DecideApprovalResult;
    [k: string]: unknown;
  };
}
/**
 * Every KUP response. On error, data is null and source/consistency may be null (resolution may have failed before they were known).
 */